{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/media-list.json
    A list or figures beside a picture. Axes: layout (figures: four figures in two columns, proof: three figures and a featured review, steps: numbered steps, posts: the latest posts, topics: topic rows with counts, contact: contact buttons and support figures), mediaSide, tone. The actions follow every layout but contact.
    Props (p): id, title, lead, badge, extras, labels, actions, layout, mediaSide, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_extras = ($p['extras'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_actions = ($p['actions'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'figures')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_1}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => (ui_t(ui_or([ui_eq($v_layout, 'steps'), ui_eq($v_layout, 'topics')])) ? '1/1' : '4/3')]])|noescape}
{/capture}
{capture $c_2}
  {if ui_t(ui_or([ui_eq($v_layout, 'figures'), ui_eq($v_layout, 'proof')]))}
    {=ui_include('blocks/media-figures.latte', ['p' => ['extras' => $v_extras, 'mode' => (ui_t(ui_eq($v_layout, 'proof')) ? 'row' : 'grid')]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'proof'))}
    {=ui_include('blocks/media-review.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'steps'))}
    {=ui_include('blocks/media-steps.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'posts'))}
    {=ui_include('blocks/media-posts.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'topics'))}
    {=ui_include('blocks/media-topics.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'contact'))}
    {=ui_include('blocks/media-contacts.latte', ['p' => ['extras' => $v_extras, 'labels' => $v_labels]])|noescape}
  {/if}
  {if ui_t(!(ui_eq($v_layout, 'contact')))}
    {=ui_include('blocks/action-group.latte', ['p' => ['primary' => ui_get($v_actions, ['cta']), 'primaryHref' => ui_get($v_actions, ['href']), 'secondary' => (ui_t(ui_eq(ui_get($v_actions, ['mode']), 'two')) ? ui_get($v_actions, ['secondary']) : null), 'secondaryHref' => ui_get($v_actions, ['secondaryHref'])]])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true, 'side' => $v_mediaSide], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_1], 'children' => $c_2])|noescape}
